181: bool File::Create(const std::wstring &Name,uint Mode)
182: {
183:   // 2025.09.03: Likely outdated info, see https://www.illumos.org/issues/2000
184:   // OpenIndiana based NAS and CIFS shares fail to set the file time if file
185:   // was created in read+write mode and some data was written and not flushed
186:   // before SetFileTime call. So we should use the write only mode if we plan
187:   // SetFileTime call and do not need to read from file.
188:   bool WriteMode=(Mode & FMF_WRITE)!=0;
189:   bool ShareRead=(Mode & FMF_SHAREREAD)!=0 || File::OpenShared;
190: #ifdef _WIN_ALL
191:   // CreateMode=Mode;
192:   uint Access=WriteMode ? GENERIC_WRITE:GENERIC_READ|GENERIC_WRITE;
193:   DWORD ShareMode=ShareRead ? FILE_SHARE_READ:0;
194: 
195:   // Windows automatically removes dots and spaces in the end of file name,
196:   // So we detect such names and process them with \\?\ prefix.
197:   wchar LastChar=GetLastChar(Name);
198:   bool Special=LastChar=='.' || LastChar==' ';
199:   
200:   if (Special && (Mode & FMF_STANDARDNAMES)==0)
201:     hFile=FILE_BAD_HANDLE;
202:   else
203:     hFile=CreateFile(Name.c_str(),Access,ShareMode,NULL,CREATE_ALWAYS,0,NULL);
204: 
205:   if (hFile==FILE_BAD_HANDLE)
206:   {
207:     std::wstring LongName;
208:     if (GetWinLongPath(Name,LongName))
209:       hFile=CreateFile(LongName.c_str(),Access,ShareMode,NULL,CREATE_ALWAYS,0,NULL);
210:   }
211: 
212: #else
213: #ifdef FILE_USE_OPEN
214:   std::string NameA;
215:   WideToChar(Name,NameA);
216:   hFile=open(NameA.c_str(),(O_CREAT|O_TRUNC) | (WriteMode ? O_WRONLY : O_RDWR),0666);
217: #else
218:   hFile=fopen(NameA.c_str(),WriteMode ? WRITEBINARY:CREATEBINARY);
219: #endif
220: #endif
221:   NewFile=true;
222:   HandleType=FILE_HANDLENORMAL;
223:   SkipClose=false;
224:   FileName=Name;
225:   return hFile!=FILE_BAD_HANDLE;
226: }
