304: bool File::Write(const void *Data,size_t Size)
305: {
306:   if (Size==0)
307:     return true;
308:   if (HandleType==FILE_HANDLESTD)
309:   {
310: #ifdef _WIN_ALL
311:     hFile=GetStdHandle(STD_OUTPUT_HANDLE);
312: #else
313:     // Cannot use the standard stdout here, because it already has wide orientation.
314:     if (hFile==FILE_BAD_HANDLE)
315:     {
316: #ifdef FILE_USE_OPEN
317:       hFile=dup(STDOUT_FILENO); // Open new stdout stream.
318: #else
319:       hFile=fdopen(dup(STDOUT_FILENO),"w"); // Open new stdout stream.
320: #endif
321:     }
322: #endif
323:   }
324:   bool Success;
325:   while (1)
326:   {
327:     Success=false;
328: #ifdef _WIN_ALL
329:     DWORD Written=0;
330:     if (HandleType!=FILE_HANDLENORMAL)
331:     {
332:       // writing to stdout can fail in old Windows if data block is too large
333:       const size_t MaxSize=0x4000;
334:       for (size_t I=0;I<Size;I+=MaxSize)
335:       {
336:         Success=WriteFile(hFile,(byte *)Data+I,(DWORD)Min(Size-I,MaxSize),&Written,NULL)!=FALSE;
337:         if (!Success)
338:           break;
339:       }
340:     }
341:     else
342:       Success=WriteFile(hFile,Data,(DWORD)Size,&Written,NULL)!=FALSE;
343: #else
344: #ifdef FILE_USE_OPEN
345:     ssize_t Written=write(hFile,Data,Size);
346:     Success=Written==Size;
347: #else
348:     int Written=fwrite(Data,1,Size,hFile);
349:     Success=Written==Size && !ferror(hFile);
350: #endif
351: #endif
352:     if (!Success && AllowExceptions && HandleType==FILE_HANDLENORMAL)
353:     {
354: #if defined(_WIN_ALL) && !defined(SFX_MODULE) && !defined(RARDLL)
355:       int ErrCode=GetLastError();
356:       int64 FilePos=Tell();
357:       uint64 FreeSize=GetFreeDisk(FileName);
358:       SetLastError(ErrCode);
359:       if (FreeSize>Size && FilePos-Size<=0xffffffff && FilePos+Size>0xffffffff)
360:         ErrHandler.WriteErrorFAT(FileName);
361: #endif
362:       if (ErrHandler.AskRepeatWrite(FileName,false))
363:       {
364: #if !defined(_WIN_ALL) && !defined(FILE_USE_OPEN)
365:         clearerr(hFile);
366: #endif
367:         if (Written<Size && Written>0)
368:           Seek(Tell()-Written,SEEK_SET);
369:         continue;
370:       }
371:       ErrHandler.WriteError(L"",FileName);
372:     }
373:     break;
374:   }
375:   LastWrite=true;
376:   return Success; // It can return false only if AllowExceptions is disabled.
377: }
