379: 
380: int File::Read(void *Data,size_t Size)
381: {
382:   if (TruncatedAfterReadError)
383:     return 0;
384: 
385:   int64 FilePos=0; // Initialized only to suppress some compilers warning.
386: 
387:   if (ReadErrorMode==FREM_IGNORE)
388:     FilePos=Tell();
389:   int TotalRead=0;
390:   while (true)
391:   {
392:     int ReadSize=DirectRead(Data,Size);
393: 
394:     if (ReadSize==-1)
395:     {
396:       ErrorType=FILE_READERROR;
397:       if (AllowExceptions)
398:         if (ReadErrorMode==FREM_IGNORE)
399:         {
400:           ReadSize=0;
401:           for (size_t I=0;I<Size;I+=512)
402:           {
403:             Seek(FilePos+I,SEEK_SET);
404:             size_t SizeToRead=Min(Size-I,512);
405:             int ReadCode=DirectRead(Data,SizeToRead);
406:             ReadSize+=(ReadCode==-1) ? 512:ReadCode;
407:             if (ReadSize!=-1)
408:               TotalRead+=ReadSize;
409:           }
410:         }
411:         else
412:         {
413:           bool Ignore=false,Retry=false,Quit=false;
414:           if (ReadErrorMode==FREM_ASK && HandleType==FILE_HANDLENORMAL && IsOpened())
415:           {
416:             ErrHandler.AskRepeatRead(FileName,Ignore,Retry,Quit);
417:             if (Retry)
418:               continue;
419:           }
420:           if (Ignore || ReadErrorMode==FREM_TRUNCATE)
421:           {
422:             TruncatedAfterReadError=true;
423:             return 0;
424:           }
425:           ErrHandler.ReadError(FileName);
426:         }
427:     }
428:     TotalRead+=ReadSize; // If ReadSize is -1, TotalRead is also set to -1 here.
429: 
430:     if (HandleType==FILE_HANDLESTD && !LineInput && ReadSize>0 && (uint)ReadSize<Size)
431:     {
432:       // Unlike regular files, for pipe we can read only as much as was
433:       // written at the other end of pipe. We had seen data coming in small
434:       // ~80 byte chunks when piping from 'type arc.rar'. Extraction code
435:       // would fail if we read an incomplete archive header from stdin.
436:       // So here we ensure that requested size is completely read.
437:       // But we return the available data immediately in "line input" mode,
438:       // when processing user's input in console prompts. Otherwise apps
439:       // piping user responses to multiple Ask() prompts can hang if no more
440:       // data is available yet and pipe isn't closed.
441:       Data=(byte*)Data+ReadSize;
442:       Size-=ReadSize;
443:       continue;
444:     }
445:     break;
446:   }
447:   if (TotalRead>0) // Can be -1 for error and AllowExceptions disabled.
448:     CurFilePos+=TotalRead;
449:   return TotalRead; // It can return -1 only if AllowExceptions is disabled.
450: }
451: 
452: 
453: // Returns -1 in case of error.
454: int File::DirectRead(void *Data,size_t Size)
455: {
456: #ifdef _WIN_ALL
457:   const size_t MaxDeviceRead=20000;
458:   const size_t MaxLockedRead=32768;
459: #endif
460:   if (HandleType==FILE_HANDLESTD)
461:   {
462: #ifdef _WIN_ALL
463: //    if (Size>MaxDeviceRead)
464: //      Size=MaxDeviceRead;
465:     hFile=GetStdHandle(STD_INPUT_HANDLE);
466: #else
467: #ifdef FILE_USE_OPEN
468:     hFile=STDIN_FILENO;
469: #else
470:     hFile=stdin;
471: #endif
472: #endif
473:   }
474: #ifdef _WIN_ALL
475:   // For pipes like 'type file.txt | rar -si arcname' ReadFile may return
476:   // data in small ~4KB blocks. It may slightly reduce the compression ratio.
477:   DWORD Read;
478:   if (!ReadFile(hFile,Data,(DWORD)Size,&Read,NULL))
479:   {
480:     if (IsDevice() && Size>MaxDeviceRead)
481:       return DirectRead(Data,MaxDeviceRead);
482:     if (HandleType==FILE_HANDLESTD && GetLastError()==ERROR_BROKEN_PIPE)
483:       return 0;
484: 
485:     // We had a bug report about failure to archive 1C database lock file
486:     // 1Cv8tmp.1CL, which is a zero length file with a region above 200 KB
487:     // permanently locked. If our first read request uses too large buffer
488:     // and if we are in -dh mode, so we were able to open the file,
489:     // we'll fail with "Read error". So now we use try a smaller buffer size
490:     // in case of lock error.
491:     if (HandleType==FILE_HANDLENORMAL && Size>MaxLockedRead &&
492:         GetLastError()==ERROR_LOCK_VIOLATION)
493:       return DirectRead(Data,MaxLockedRead);
494: 
495:     return -1;
496:   }
497:   return Read;
498: #else
499: #ifdef FILE_USE_OPEN
500:   ssize_t ReadSize=read(hFile,Data,Size);
501:   if (ReadSize==-1)
502:     return -1;
503:   return (int)ReadSize;
504: #else
505:   if (LastWrite)
506:   {
507:     fflush(hFile);
508:     LastWrite=false;
509:   }
510:   clearerr(hFile);
511:   size_t ReadSize=fread(Data,1,Size,hFile);
512:   if (ferror(hFile))
513:     return -1;
514:   return (int)ReadSize;
515: #endif
516: #endif
517: }
