526: 
527: bool File::RawSeek(int64 Offset,int Method)
528: {
529:   if (hFile==FILE_BAD_HANDLE)
530:     return true;
531:   if (!IsSeekable()) // To extract archives from stdin with -si.
532:   {
533:     // We tried to dynamically allocate 32 KB buffer here, but it improved
534:     // speed in Windows 10 by mere ~1.5%.
535:     byte Buf[4096];
536:     if (Method==SEEK_CUR || Method==SEEK_SET && Offset>=CurFilePos)
537:     {
538:       uint64 SkipSize=Method==SEEK_CUR ? Offset:Offset-CurFilePos;
539:       while (SkipSize>0) // Reading to emulate seek forward.
540:       {
541:         int ReadSize=Read(Buf,(size_t)Min(SkipSize,ASIZE(Buf)));
542:         if (ReadSize<=0)
543:           return false;
544:         SkipSize-=ReadSize;
545:         CurFilePos+=ReadSize;
546:       }
547:       return true;
548:     }
549:     // May need it in FileLength() in Archive::UnexpEndArcMsg() when unpacking
550:     // RAR 4.x archives without the end of archive block created with -en.
551:     if (Method==SEEK_END)
552:     {
553:       int ReadSize;
554:       while ((ReadSize=Read(Buf,ASIZE(Buf)))>0)
555:         CurFilePos+=ReadSize;
556:       return true;
557:     }
558: 
559:     return false; // Backward seek on unseekable file.
560:   }
561:   if (Offset<0 && Method!=SEEK_SET)
562:   {
563:     Offset=(Method==SEEK_CUR ? Tell():FileLength())+Offset;
564:     Method=SEEK_SET;
565:   }
566: #ifdef _WIN_ALL
567:   LONG HighDist=(LONG)(Offset>>32);
568:   if (SetFilePointer(hFile,(LONG)Offset,&HighDist,Method)==0xffffffff &&
569:       GetLastError()!=NO_ERROR)
570:     return false;
571: #else
572:   LastWrite=false;
573: #ifdef FILE_USE_OPEN
574:   if (lseek(hFile,(off_t)Offset,Method)==-1)
575:     return false;
576: #elif defined(_LARGEFILE_SOURCE) && !defined(_OSF_SOURCE) && !defined(__VMS)
577:   if (fseeko(hFile,Offset,Method)!=0)
578:     return false;
579: #else
580:   if (fseek(hFile,(long)Offset,Method)!=0)
581:     return false;
582: #endif
583: #endif
584:   return true;
585: }
