588: int64 File::Tell()
589: {
590:   if (hFile==FILE_BAD_HANDLE)
591:     if (AllowExceptions)
592:       ErrHandler.SeekError(FileName);
593:     else
594:       return -1;
595:   if (!IsSeekable())
596:     return CurFilePos;
597: #ifdef _WIN_ALL
598:   LONG HighDist=0;
599:   uint LowDist=SetFilePointer(hFile,0,&HighDist,FILE_CURRENT);
600:   if (LowDist==0xffffffff && GetLastError()!=NO_ERROR)
601:     if (AllowExceptions)
602:       ErrHandler.SeekError(FileName);
603:     else
604:       return -1;
605:   return INT32TO64(HighDist,LowDist);
606: #else
607: #ifdef FILE_USE_OPEN
608:   return lseek(hFile,0,SEEK_CUR);
609: #elif defined(_LARGEFILE_SOURCE) && !defined(_OSF_SOURCE)
610:   return ftello(hFile);
611: #else
612:   return ftell(hFile);
613: #endif
614: #endif
615: }
