715: void File::SetCloseFileTimeByName(const std::wstring &Name,RarTime *ftm,RarTime *fta)
716: {
717: #ifdef _UNIX
718:   bool setm=ftm!=NULL && ftm->IsSet();
719:   bool seta=fta!=NULL && fta->IsSet();
720:   if (setm || seta)
721:   {
722:     std::string NameA;
723:     WideToChar(Name,NameA);
724: 
725: #ifdef UNIX_TIME_NS
726:     timespec times[2];
727:     times[0].tv_sec=seta ? fta->GetUnix() : 0;
728:     times[0].tv_nsec=seta ? long(fta->GetUnixNS()%1000000000) : UTIME_NOW;
729:     times[1].tv_sec=setm ? ftm->GetUnix() : 0;
730:     times[1].tv_nsec=setm ? long(ftm->GetUnixNS()%1000000000) : UTIME_NOW;
731:     utimensat(AT_FDCWD,NameA.c_str(),times,0);
732: #else
733:     utimbuf ut;
734:     if (setm)
735:       ut.modtime=ftm->GetUnix();
736:     else
737:       ut.modtime=fta->GetUnix(); // Need to set something, cannot left it 0.
738:     if (seta)
739:       ut.actime=fta->GetUnix();
740:     else
741:       ut.actime=ut.modtime; // Need to set something, cannot left it 0.
742:     utime(NameA.c_str(),&ut);
743: #endif
744:   }
745: #endif
746: }
