810: #ifndef SFX_MODULE
811: int64 File::Copy(File &Dest,int64 Length)
812: {
813:   bool CopyAll=(Length==INT64NDF);
814: 
815:   // Adjust the buffer size to data size. So we do not waste too much time
816:   // to vector initialization when copying many small data blocks like
817:   // when updating an archive with many small files.
818:   size_t BufSize=File::CopyBufferSize();
819:   if (!CopyAll && Length<(int64)BufSize)
820:     BufSize=(size_t)Length;
821: 
822:   std::vector<byte> Buffer(BufSize);
823:   int64 CopySize=0;
824: 
825:   while (CopyAll || Length>0)
826:   {
827:     Wait();
828:     size_t SizeToRead=(!CopyAll && Length<(int64)Buffer.size()) ? (size_t)Length:Buffer.size();
829:     byte *Buf=Buffer.data();
