207: void ThreadPool::PoolThreadLoop()
208: {
209:   QueueEntry Task;
210:   while (GetQueuedTask(&Task))
211:   {
212:     Task.Proc(Task.Param);
213:     
214:     CriticalSectionStart(&CritSection); 
215:     if (--ActiveThreads == 0)
216:     {
217: #ifdef _WIN_ALL
218:       SetEvent(NoneActive);
219: #elif defined(_UNIX)
220:       pthread_mutex_lock(&AnyActiveMutex);
221:       AnyActive=false;
222:       pthread_cond_signal(&AnyActiveCond);
223:       pthread_mutex_unlock(&AnyActiveMutex);
224: #endif
225:     }
226:     CriticalSectionEnd(&CritSection); 
227:   }
228: }
