231: bool ThreadPool::GetQueuedTask(QueueEntry *Task)
232: {
233: #ifdef _WIN_ALL
234:   CWaitForSingleObject(QueuedTasksCnt);
235: #elif defined(_UNIX)
236:   pthread_mutex_lock(&QueuedTasksCntMutex);
237:   while (QueuedTasksCnt==0)
238:     cpthread_cond_wait(&QueuedTasksCntCond,&QueuedTasksCntMutex);
239:   QueuedTasksCnt--;
240:   pthread_mutex_unlock(&QueuedTasksCntMutex);
241: #endif
242: 
243:   if (Closing)
244:     return false;
245: 
246:   CriticalSectionStart(&CritSection); 
247: 
248:   *Task = TaskQueue[QueueBottom];
249:   QueueBottom = (QueueBottom + 1) % ASIZE(TaskQueue);
250: 
251:   CriticalSectionEnd(&CritSection); 
252: 
253:   return true;
254: }
