400: // Returns the position to rightmost digit of volume number or beginning
401: // of file name if numeric part is missing.
402: size_t GetVolNumPos(const std::wstring &ArcName)
403: {
404:   // We do not want to increment any characters in path component.
405:   size_t NamePos=GetNamePos(ArcName);
406: 
407:   if (NamePos==ArcName.size())
408:     return NamePos;
409: 
410:   // Pointing to last name character.
411:   size_t Pos=ArcName.size()-1;
412: 
413:   // Skipping the archive extension.
414:   while (!IsDigit(ArcName[Pos]) && Pos>NamePos)
415:     Pos--;
416: 
417:   // Skipping the numeric part of name.
418:   size_t NumPos=Pos;
419:   while (IsDigit(ArcName[NumPos]) && NumPos>NamePos)
420:     NumPos--;
421: 
422:   // Searching for first numeric part in names like name.part##of##.rar.
423:   // Stop search on the first dot.
424:   while (NumPos>NamePos && ArcName[NumPos]!='.')
425:   {
426:     if (IsDigit(ArcName[NumPos]))
427:     {
428:       // Validate the first numeric part only if it has a dot somewhere 
429:       // before it.
430:       auto DotPos=ArcName.find('.',NamePos);
431:       if (DotPos!=std::wstring::npos && DotPos<NumPos)
432:         Pos=NumPos;
433:       break;
434:     }
435:     NumPos--;
436:   }
437:   return Pos;
438: }
439: 
440: 
441: void NextVolumeName(std::wstring &ArcName,bool OldNumbering)
442: {
443:   auto DotPos=GetExtPos(ArcName);
444:   if (DotPos==std::wstring::npos)
445:   {
446:     ArcName+=L".rar";
447:     DotPos=GetExtPos(ArcName);
448:   }
449:   else
450:     if (DotPos+1==ArcName.size() || CmpExt(ArcName,L"exe") || CmpExt(ArcName,L"sfx"))
451:       SetExt(ArcName,L"rar");
452: 
453:   if (!OldNumbering)
454:   {
455:     size_t NumPos=GetVolNumPos(ArcName);
456: 
457:     // We should not check for IsDigit() here and should increment
458:     // even non-digits. If we got a corrupt archive with volume flag,
459:     // but without numeric part, we still need to modify its name somehow,
460:     // so "while (Exist()) {NextVolumeName();}" loops do not run infinitely.
461:     while (++ArcName[NumPos]=='9'+1)
462:     {
463:       ArcName[NumPos]='0';
464:       if (NumPos==0)
465:         break;
466:       NumPos--;
467:       if (!IsDigit(ArcName[NumPos]))
468:       {
469:         // Convert .part:.rar (.part9.rar after increment) to part10.rar.
470:         ArcName.insert(NumPos+1,1,'1');
471:         break;
472:       }
473:     }
474:   }
475:   else
476:   {
477:     // If extension is shorter than 3 characters, set it to "rar" to simplify
478:     // further processing.
479:     if (ArcName.size()-DotPos<3)
480:       ArcName.replace(DotPos+1,std::wstring::npos,L"rar");
481: 
482:     if (!IsDigit(ArcName[DotPos+2]) || !IsDigit(ArcName[DotPos+3]))
483:       ArcName.replace(DotPos+2,std::wstring::npos,L"00"); // From .rar to .r00.
484:     else
485:     {
486:       auto NumPos=ArcName.size()-1;  // Set to last character.
487:       while (++ArcName[NumPos]=='9'+1)
488:         if (NumPos==0 || ArcName[NumPos-1]=='.')
489:         {
490:           ArcName[NumPos]='a'; // From .999 to .a00 if started from .001 or for too short names.
491:           break;
492:         }
493:         else
494:           ArcName[NumPos--]='0';
495:     }
496:   }
497: }
