500: bool IsNameUsable(const std::wstring &Name)
501: {
502:   // We were asked to apply Windows-like conversion in Linux in case
503:   // files are unpacked to Windows share. This code is invoked only
504:   // if file failed to be created, so it doesn't affect extraction
505:   // of Unix compatible names to native Unix drives.
506: #ifdef _UNIX
507:   // Windows shares in Unix do not allow the drive letter,
508:   // so unlike Windows version, we check all characters here.
509:   if (Name.find(':')!=std::wstring::npos)
510:     return false;
511: #else
512:   if (Name.find(':',2)!=std::wstring::npos)
513:     return false;
514: #endif
515:   for (size_t I=0;I<Name.size();I++)
516:   {
517:     if ((uint)Name[I]<32)
518:       return false;
519: 
520:      // It is for Windows shares in Unix. We can create such names in Windows.
521: #ifdef _UNIX
522:     // No spaces or dots before the path separator are allowed in Windows
523:     // shares. But they are allowed and automatically removed at the end of
524:     // file or folder name, so it is useless to replace them here.
525:     // Since such files or folders are created successfully, a supposed
526:     // conversion here would never be invoked.
527:     if ((Name[I]==' ' || Name[I]=='.') && IsPathDiv(Name[I+1]))
528:       return false;
529: #endif
530:   }
531:   return !Name.empty() && Name.find_first_of(L"?*<>|\"")==std::wstring::npos;
532: }
533: 
534: 
535: void MakeNameUsable(std::wstring &Name,bool Extended)
536: {
537:   size_t StartPos=0;
538: #ifdef _WIN_ALL
539:   // 2025.07.03: Do not replace '?' and ':' in \\?\d: in the beginning of path
540:   // in Windows.
541:   if (Name.size()>5 && starts_with(Name,L"\\\\?\\") && IsDriveLetter(&Name[4]))
542:     StartPos=6;
543: #endif
544: 
545:   for (size_t I=StartPos;I<Name.size();I++)
546:   {
547:     if (wcschr(Extended ? L"?*<>|\"":L"?*",Name[I])!=NULL || 
548:         Extended && (uint)Name[I]<32)
549:       Name[I]='_';
550: #ifdef _UNIX
551:     // We were asked to apply Windows-like conversion in Linux in case
552:     // files are unpacked to Windows share. This code is invoked only
553:     // if file failed to be created, so it doesn't affect extraction
554:     // of Unix compatible names to native Unix drives.
555:     if (Extended)
556:     {
557:       // Windows shares in Unix do not allow the drive letter,
558:       // so unlike Windows version, we check all characters here.
559:       if (Name[I]==':')
560:         Name[I]='_';
561: 
562:       // No spaces or dots before the path separator are allowed on Windows
563:       // shares. But they are allowed and automatically removed at the end of
564:       // file or folder name, so we need to replace them only before
565:       // the path separator, but not at the end of file name.
566:       // Since such files or folders are created successfully, a supposed
567:       // conversion at the end of file name would never be invoked here.
568:       // While converting dots, we preserve "." and ".." path components,
569:       // such as when specifying ".." in the destination path.
570:       if (IsPathDiv(Name[I+1]) && (Name[I]==' ' || Name[I]=='.' && I>0 &&
571:           !IsPathDiv(Name[I-1]) && (Name[I-1]!='.' || I>1 && !IsPathDiv(Name[I-2]))))
572:         Name[I]='_';
573:     }
574: #else
575:     if (I>1 && Name[I]==':')
576:       Name[I]='_';
577: #endif
578:   }
579: }
