654: void ConvertNameToFull(const std::wstring &Src,std::wstring &Dest)
655: {
656:   if (Src.empty())
657:   {
658:     Dest.clear();
659:     return;
660:   }
661: #ifdef _WIN_ALL
662:   {
663:     DWORD Code=GetFullPathName(Src.c_str(),0,NULL,NULL); // Get the buffer size.
664:     if (Code!=0)
665:     {
666:       std::vector<wchar> FullName(Code);
667:       Code=GetFullPathName(Src.c_str(),(DWORD)FullName.size(),FullName.data(),NULL);
668: 
669:       if (Code>0 && Code<=FullName.size())
670:       {
671:         Dest=FullName.data();
672:         return;
673:       }
674:     }
675: 
676:     std::wstring LongName;
677:     if (GetWinLongPath(Src,LongName)) // Failed with normal name, try long.
678:     {
679:       Code=GetFullPathName(LongName.c_str(),0,NULL,NULL); // Get the buffer size.
680:       if (Code!=0)
681:       {
682:         std::vector<wchar> FullName(Code);
683:         Code=GetFullPathName(LongName.c_str(),(DWORD)FullName.size(),FullName.data(),NULL);
684: 
685:         if (Code>0 && Code<=FullName.size())
686:         {
687:           Dest=FullName.data();
688:           return;
689:         }
690:       }
691:     }
692:     if (Src!=Dest)
693:       Dest=Src; // Copy source to destination in case of failure.
694:   }
695: #elif defined(_UNIX)
696:   if (IsFullPath(Src))
697:     Dest.clear();
698:   else
699:   {
700:     std::vector<char> CurDirA(MAXPATHSIZE);
701:     if (getcwd(CurDirA.data(),CurDirA.size())==NULL)
702:       CurDirA[0]=0;
703:     CharToWide(CurDirA.data(),Dest);
704:     AddEndSlash(Dest);
705:   }
706:   Dest+=Src;
707: #else
708:   Dest=Src;
709: #endif
710: }
