76: // For masks like dir1\dir2*\*.ext in non-recursive mode.
77: bool ScanTree::ExpandFolderMask()
78: {
79:   bool WildcardFound=false;
80:   uint SlashPos=0;
81:   for (uint I=0;I<CurMask.size();I++)
82:   {
83:     if (CurMask[I]=='?' || CurMask[I]=='*')
84:       WildcardFound=true;
85:     if (WildcardFound && IsPathDiv(CurMask[I]))
86:     {
87:       // First path separator position after folder wildcard mask.
88:       // In case of dir1\dir2*\dir3\name.ext mask it may point not to file
89:       // name, so we cannot use PointToName() here.
90:       SlashPos=I; 
91:       break;
92:     }
93:   }
94: 
95:   std::wstring Mask=CurMask.substr(0,SlashPos);
96: 
97:   // Prepare the list of all folders matching the wildcard mask.
98:   ExpandedFolderList.Reset();
99:   FindFile Find;
100:   Find.SetMask(Mask);
101:   FindData FD;
102:   while (Find.Next(&FD))
103:     if (FD.IsDir)
104:     {
105:       FD.Name+=CurMask.substr(SlashPos);
106: 
107:       // Treat dir*\*, dir*\*.* or dir*\ as dir, so empty 'dir' is also matched
108:       // by such mask. Skipping empty dir with dir*\*.* confused some users.
109:       std::wstring LastMask=PointToName(FD.Name);
110:       if (LastMask==L"*" || LastMask==L"*.*" || LastMask.empty())
111:         RemoveNameFromPath(FD.Name);
112: 
113:       ExpandedFolderList.AddString(FD.Name);
114:     }
115:   if (ExpandedFolderList.ItemsCount()==0)
116:     return false;
117:   // Return the first matching folder name now.
118:   ExpandedFolderList.GetString(CurMask);
119:   return true;
120: }
