123: // For masks like dir1\dir2*\file.ext this function sets 'dir1' recursive mask
124: // and '*\dir2*\file.ext' filter. Masks without folder wildcards are
125: // returned as is.
126: bool ScanTree::GetFilteredMask()
127: {
128:   // If we have some matching folders left for non-recursive folder wildcard
129:   // mask, we return it here.
130:   if (ExpandedFolderList.ItemsCount()>0 && ExpandedFolderList.GetString(CurMask))
131:     return true;
132: 
133:   FolderWildcards=false;
134:   FilterList.Reset();
135:   if (!FileMasks->GetString(CurMask))
136:     return false;
137: 
138:   // Check if folder wildcards present.
139:   bool WildcardFound=false;
140:   uint FolderWildcardCount=0;
141:   uint SlashPos=0;
142:   uint StartPos=0;
143: #ifdef _WIN_ALL // Not treat the special NTFS \\?\d: path prefix as a wildcard.
144:   if (starts_with(CurMask,L"\\\\?\\"))
145:     StartPos=4;
146: #endif
147:   for (uint I=StartPos;I<CurMask.size();I++)
148:   {
149:     if (CurMask[I]=='?' || CurMask[I]=='*')
150:       WildcardFound=true;
151:     if (IsPathDiv(CurMask[I]) || IsDriveDiv(CurMask[I]))
152:     {
153:       if (WildcardFound)
154:       {
155:         // Calculate a number of folder wildcards in current mask.
156:         FolderWildcardCount++;
157:         WildcardFound=false;
158:       }
159:       if (FolderWildcardCount==0)
160:         SlashPos=I; // Slash position before first folder wildcard mask.
161:     }
162:   }
163:   if (FolderWildcardCount==0)
164:     return true;
165:   FolderWildcards=true; // Global folder wildcards flag.
166: 
167:   // If we have only one folder wildcard component and -r is missing or -r-
168:   // is specified, prepare matching folders in non-recursive mode.
169:   // We assume -r for masks like dir1*\dir2*\file*, because it is complicated
170:   // to fast find them using OS file find API call.
171:   if ((Recurse==RECURSE_NONE || Recurse==RECURSE_DISABLE) && FolderWildcardCount==1)
172:     return ExpandFolderMask();
173: 
174:   // Convert path\dir*\ to *\dir filter to search for 'dir' in all 'path' subfolders.
175:   std::wstring Filter=L"*";
176:   AddEndSlash(Filter); // Path separator is OS dependent, so we set it here instead of variable declaration.
177: 
178:   // SlashPos might point or not point to path separator for masks like 'dir*', '\dir*' or 'd:dir*'
179:   std::wstring WildName=IsPathDiv(CurMask[SlashPos]) || IsDriveDiv(CurMask[SlashPos]) ? CurMask.substr(SlashPos+1) : CurMask.substr(SlashPos);
180:   Filter+=WildName;
181: 
182:   // Treat dir*\* or dir*\*.* as dir\, so empty 'dir' is also matched
183:   // by such mask. Skipping empty dir with dir*\*.* confused some users.
184:   std::wstring LastMask=PointToName(Filter);
185:   if (LastMask==L"*" || LastMask==L"*.*")
186:     GetPathWithSep(Filter,Filter);
187: 
188:   FilterList.AddString(Filter);
189: 
190:   bool RelativeDrive=IsDriveDiv(CurMask[SlashPos]);
191:   if (RelativeDrive)
192:     SlashPos++; // Use "d:" instead of "d" for d:* mask.
193: 
194:   CurMask.erase(SlashPos);
195: 
196:   if (!RelativeDrive) // Keep d: mask as is, not convert to d:\*
197:   {
198:     // We need to append "\*" both for -ep1 to work correctly and to
199:     // convert d:\* masks previously truncated to d: back to original form.
200:     AddEndSlash(CurMask);
201:     CurMask+=MASKALL;
202:   }
203:   return true;
204: }
