207: bool ScanTree::GetNextMask()
208: {
209:   if (!GetFilteredMask())
210:     return false;
211: #ifdef _WIN_ALL
212:   UnixSlashToDos(CurMask,CurMask);
213: #endif
214: 
215:   // We shall set it before appending the path separator to \\server\share
216:   // UNC mask below, so "rar a -ep1 arc \\server\share" includes paths
217:   // starting from "share\".
218:   SpecPathLength=GetNamePos(CurMask);
219: 
220:   // We prefer to scan entire disk if mask like \\server\share\ or c:\
221:   // is specified even without -r, but not with -r-. Use \\server\share\*.*,
222:   // c:\*.* mask or -r- to scan only the root directory. Note that UNC names
223:   // are possible both in Win32 and Unix, just with proper path separators.
224:   if (Recurse!=RECURSE_DISABLE)
225:     if (CurMask.size()>2 && CurMask[0]==CPATHDIVIDER && CurMask[1]==CPATHDIVIDER)
226:     {
227:       auto Slash=CurMask.find(CPATHDIVIDER,2);
228:       if (Slash!=std::wstring::npos)
229:       {
230:         Slash=CurMask.find(CPATHDIVIDER,Slash+1);
231:         // If path separator is mssing or it is the last string character.
232:         ScanEntireDisk=Slash==std::wstring::npos || 
233:                        Slash!=std::wstring::npos && Slash+1==CurMask.size();
234: 
235:         // Win32 FindFirstFile fails for \\server\share names without
236:         // the trailing backslash. So we add it here.
237:         if (Slash==std::wstring::npos)
238:           CurMask+=CPATHDIVIDER;
239:       }
240:     }
241:     else
242:       ScanEntireDisk=IsDriveLetter(CurMask) && IsPathDiv(CurMask[2]) && CurMask[3]==0;
243: 
244:   // Calculate the name position again, because we could modify UNC path above.
245:   auto NamePos=GetNamePos(CurMask);
246:   std::wstring Name=CurMask.substr(NamePos);
247:   if (Name.empty())
248:     CurMask+=MASKALL;
249:   if (Name==L"." || Name==L"..")
250:   {
251:     AddEndSlash(CurMask);
252:     CurMask+=MASKALL;
253:   }
254:   Depth=0;
255: 
256:   OrigCurMask=CurMask;
257: 
258:   return true;
259: }
