492:     // Do not display an error if we cannot scan contents of
493:     // "System Volume Information" folder. Normally it is not accessible.
494:     if (CurMask.find(L"System Volume Information\\")!=std::wstring::npos)
495:       Error=false;
496:   }
497: #endif
498: 
499:   if (Error && Cmd!=NULL && Cmd->ExclCheck(CurMask,false,true,true))
500:     Error=false;
501: 
502:   if (Error)
503:   {
504:     if (ErrDirList!=NULL)
505:       ErrDirList->AddString(CurMask);
506:     if (ErrDirSpecPathLength!=NULL)
507:       ErrDirSpecPathLength->push_back((uint)SpecPathLength);
508:     std::wstring FullName;
509:     // This conversion works for wildcard masks too.
510:     ConvertNameToFull(CurMask,FullName);
